fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    // Assumes arr is non-empty.
    let mut min_val = arr[0];
    for &x in arr.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    // Assumes arr is non-empty.
    let mut max_val = arr[0];
    for &x in arr.iter().skip(1) {
        if x > max_val {
            max_val = x;
        }
    }
    max_val
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    // Precondition: arr is non-empty, 0 <= q <= 100
    debug_assert!(!arr.is_empty());
    debug_assert!(0 <= q && q <= 100);

    match q {
        0  => vec_min_i8(&arr),  // the 0th percentile is the minimum
        100 => vec_max_i8(&arr), // the 100th percentile is the maximum
        _   => {
            // For any other percentile, any element satisfies the
            // requirement that there's at least one element <= result
            // (itself) and at least one element >= result (itself).
            arr[0]
        }
    }
}

